const QUESTIONS = [{"id": 1, "category": "Mechanical Fundamentals", "question": "What is the SI unit of force?", "options": ["Joule", "Watt", "Pascal", "Newton"], "answer": 3, "explanation": "Force equals mass multiplied by acceleration and is measured in newtons."}, {"id": 2, "category": "Mechanical Fundamentals", "question": "A 20 kg mass accelerates at 3 m/s². What net force acts on it?", "options": ["23 N", "600 N", "6.7 N", "60 N"], "answer": 3, "explanation": "F = ma = 20 × 3 = 60 N."}, {"id": 3, "category": "Mechanical Fundamentals", "question": "A 100 N force acts perpendicular to a 0.5 m lever. What torque results?", "options": ["200 N·m", "0.5 N·m", "50 N·m", "100 N·m"], "answer": 2, "explanation": "Torque equals force times perpendicular lever arm."}, {"id": 4, "category": "Mechanical Fundamentals", "question": "What does Young's modulus describe in the linear elastic region?", "options": ["Torque divided by angle for any shaft", "Stress divided by strain", "Force divided by speed", "Density divided by pressure"], "answer": 1, "explanation": "Young's modulus measures axial elastic stiffness: E = stress/strain."}, {"id": 5, "category": "Mechanical Fundamentals", "question": "Which loading condition most commonly causes fatigue failure?", "options": ["Repeated fluctuating stress", "No applied load", "One constant low compressive load", "Uniform temperature at rest"], "answer": 0, "explanation": "Fatigue damage accumulates under repeated stress cycles."}, {"id": 6, "category": "Mechanical Fundamentals", "question": "What is the normal stress in a bar carrying 10 kN over 100 mm²?", "options": ["100 MPa", "1 MPa", "1000 MPa", "10 MPa"], "answer": 0, "explanation": "Stress = 10000/100 = 100 N/mm² = 100 MPa."}, {"id": 7, "category": "Mechanical Fundamentals", "question": "What is the main function of a shaft key?", "options": ["Absorb all axial loads", "Seal a bearing housing", "Measure shaft speed", "Transmit torque between shaft and hub"], "answer": 3, "explanation": "A key prevents relative rotation between a shaft and its mounted hub."}, {"id": 8, "category": "Mechanical Fundamentals", "question": "Which property measures resistance to indentation?", "options": ["Ductility", "Thermal conductivity", "Hardness", "Specific heat"], "answer": 2, "explanation": "Hardness is resistance to localized indentation or scratching."}, {"id": 9, "category": "Mechanical Fundamentals", "question": "Which material behavior is described by ductility?", "options": ["Resistance to electrical current", "Elastic stiffness alone", "Resistance to heat flow", "Plastic deformation before fracture"], "answer": 3, "explanation": "Ductile materials can undergo appreciable plastic strain before breaking."}, {"id": 10, "category": "Mechanical Fundamentals", "question": "Why are expansion joints used in long hot pipelines?", "options": ["Increase pipe wall thickness", "Permanently prevent corrosion", "Accommodate thermal movement", "Eliminate the need for supports"], "answer": 2, "explanation": "Expansion joints accommodate movement within their design limits."}, {"id": 11, "category": "Mechanical Fundamentals", "question": "For a free metal bar, which equation gives thermal expansion?", "options": ["ΔL = F/A", "ΔL = L/αΔT", "ΔL = mcpΔT", "ΔL = αLΔT"], "answer": 3, "explanation": "Free linear expansion depends on expansion coefficient, original length and temperature change."}, {"id": 12, "category": "Mechanical Fundamentals", "question": "What does a factor of safety compare in a simple strength calculation?", "options": ["Speed to torque", "Failure strength to allowable working stress", "Mass to volume", "Power to energy"], "answer": 1, "explanation": "A simple strength safety factor is strength divided by working stress."}, {"id": 13, "category": "Mechanical Fundamentals", "question": "Which component normally supports a rotating shaft?", "options": ["Strainer", "Thermowell", "Gasket", "Bearing"], "answer": 3, "explanation": "Bearings support shafts and allow controlled relative motion."}, {"id": 14, "category": "Mechanical Fundamentals", "question": "Why is a calibrated torque wrench used?", "options": ["Measure pipe flow", "Apply specified tightening torque", "Detect bearing cracks", "Set motor frequency"], "answer": 1, "explanation": "Controlled torque helps achieve the required joint preload."}, {"id": 15, "category": "Mechanical Fundamentals", "question": "What is a common consequence of excessive bolt tightening?", "options": ["Bolt yielding or thread damage", "Guaranteed leak prevention", "Reduced bolt stress", "Improved calibration"], "answer": 0, "explanation": "Overtightening can permanently stretch fasteners and damage threads."}, {"id": 16, "category": "Pumps and Fluid Systems", "question": "What energy does a centrifugal pump primarily add to liquid?", "options": ["Electrical charge", "Nuclear energy", "Chemical energy", "Mechanical energy expressed as head"], "answer": 3, "explanation": "The impeller transfers mechanical energy to the liquid."}, {"id": 17, "category": "Pumps and Fluid Systems", "question": "What is pump cavitation?", "options": ["Air cooling in a motor", "Vapor bubbles forming and collapsing in low-pressure regions", "A permanent increase in viscosity", "Normal liquid expansion in a tank"], "answer": 1, "explanation": "Local pressure below vapor pressure creates bubbles that collapse at higher pressure."}, {"id": 18, "category": "Pumps and Fluid Systems", "question": "Which change generally increases available NPSH for a tank-fed pump?", "options": ["Increase suction-line losses", "Raise liquid level above the pump", "Raise liquid temperature", "Reduce tank absolute pressure"], "answer": 1, "explanation": "Greater suction static head increases NPSH available, other factors unchanged."}, {"id": 19, "category": "Pumps and Fluid Systems", "question": "Why should a non-self-priming centrifugal pump be primed?", "options": ["Harden the impeller", "Increase motor voltage", "Remove all discharge valves", "Fill the casing and suction path with liquid"], "answer": 3, "explanation": "Air prevents the pump from developing its intended liquid head."}, {"id": 20, "category": "Pumps and Fluid Systems", "question": "What is the purpose of a pump mechanical seal?", "options": ["Increase motor speed", "Limit leakage where the shaft passes through the casing", "Filter the suction water", "Support all radial loads"], "answer": 1, "explanation": "Seal faces restrict leakage around the rotating shaft."}, {"id": 21, "category": "Pumps and Fluid Systems", "question": "Where is a centrifugal pump's best efficiency point?", "options": ["The flow and head where efficiency is highest", "At zero flow in every pump", "At maximum motor temperature", "At the highest possible discharge pressure"], "answer": 0, "explanation": "BEP is a specific operating point on the pump performance curve."}, {"id": 22, "category": "Pumps and Fluid Systems", "question": "What is the usual purpose of a discharge check valve?", "options": ["Remove dissolved gases", "Prevent reverse flow", "Prime every pump automatically", "Control motor current directly"], "answer": 1, "explanation": "A check valve permits flow in one direction and resists reverse flow."}, {"id": 23, "category": "Pumps and Fluid Systems", "question": "Two similar pumps in series mainly increase what at a given flow?", "options": ["Total head", "Atmospheric pressure", "Fluid density", "Pipe diameter"], "answer": 0, "explanation": "For series operation, the heads add at the same flow."}, {"id": 24, "category": "Pumps and Fluid Systems", "question": "Two similar pumps in parallel mainly increase what at a given head?", "options": ["Supply frequency", "Liquid boiling point", "Combined flow capacity", "Individual impeller diameter"], "answer": 2, "explanation": "At a common head, the flows from parallel pumps add."}, {"id": 25, "category": "Pumps and Fluid Systems", "question": "For the same centrifugal pump under affinity-law assumptions, doubling speed changes flow by approximately what factor?", "options": ["0.5", "4", "2", "8"], "answer": 2, "explanation": "Flow is proportional to rotational speed for dynamically similar operation."}, {"id": 26, "category": "Pumps and Fluid Systems", "question": "Under the same affinity-law assumptions, doubling speed changes head by approximately what factor?", "options": ["4", "8", "0.25", "2"], "answer": 0, "explanation": "Head is proportional to the square of speed."}, {"id": 27, "category": "Pumps and Fluid Systems", "question": "Under the same affinity-law assumptions, doubling speed changes power by approximately what factor?", "options": ["8", "2", "0.5", "4"], "answer": 0, "explanation": "Power is proportional to the cube of speed; motor and system limits still apply."}, {"id": 28, "category": "Pumps and Fluid Systems", "question": "A pump gives 20 m head at 0.01 m³/s with water. What hydraulic power is delivered, using g = 9.81 m/s²?", "options": ["1.96 kW", "19.6 kW", "196 kW", "0.196 kW"], "answer": 0, "explanation": "Hydraulic power = ρgQH = 1000 × 9.81 × 0.01 × 20 W."}, {"id": 29, "category": "Pumps and Fluid Systems", "question": "Why must a positive-displacement pump have suitable overpressure protection?", "options": ["Its motor never overloads", "A blocked discharge can rapidly create dangerous pressure", "It cannot pump viscous liquids", "Its flow always becomes zero safely"], "answer": 1, "explanation": "Positive-displacement pumps continue displacing fluid against restrictions."}, {"id": 30, "category": "Pumps and Fluid Systems", "question": "A pump's flow falls while suction-strainer differential pressure rises. What is the most likely issue?", "options": ["Reduced suction resistance", "A clogged suction strainer", "An improved pump efficiency", "A larger impeller"], "answer": 1, "explanation": "Increasing strainer differential pressure indicates increasing flow resistance."}, {"id": 31, "category": "Bearings, Alignment and Lubrication", "question": "What is the main purpose of lubrication in a bearing?", "options": ["Reduce friction and wear by separating surfaces", "Increase abrasive contact", "Replace shaft alignment", "Prevent every possible failure"], "answer": 0, "explanation": "A suitable lubricant film limits direct surface contact."}, {"id": 32, "category": "Bearings, Alignment and Lubrication", "question": "What can excessive grease in a rolling bearing cause?", "options": ["Zero friction", "Churning and overheating", "Guaranteed cooling", "Automatic seal repair"], "answer": 1, "explanation": "Too much grease can increase internal resistance and heat."}, {"id": 33, "category": "Bearings, Alignment and Lubrication", "question": "Why should different greases not be mixed without verification?", "options": ["Color guarantees compatibility", "Mixing always improves viscosity", "Their thickeners and additives may be incompatible", "All greases have identical chemistry"], "answer": 2, "explanation": "Compatibility must be checked using approved lubricant information."}, {"id": 34, "category": "Bearings, Alignment and Lubrication", "question": "What does viscosity describe?", "options": ["Its acidity alone", "Its mass alone", "A fluid's resistance to flow", "Its electrical frequency"], "answer": 2, "explanation": "Viscosity describes internal resistance to deformation and flow."}, {"id": 35, "category": "Bearings, Alignment and Lubrication", "question": "What usually happens to lubricating-oil viscosity as temperature rises?", "options": ["It is unchanged for every oil", "It decreases", "It always increases", "It becomes zero immediately"], "answer": 1, "explanation": "Most lubricating oils become less viscous as temperature increases."}, {"id": 36, "category": "Bearings, Alignment and Lubrication", "question": "Which instrument is commonly used for precision shaft alignment?", "options": ["Laser alignment system", "Clamp ammeter alone", "Anemometer", "pH meter"], "answer": 0, "explanation": "Laser systems measure shaft alignment offsets and angular errors."}, {"id": 37, "category": "Bearings, Alignment and Lubrication", "question": "What is soft foot on a machine?", "options": ["A machine foot does not sit properly on its support", "A flexible rubber coupling", "A lubricated anchor bolt", "Normal bearing clearance"], "answer": 0, "explanation": "Uneven foot support can distort the machine when bolts are tightened."}, {"id": 38, "category": "Bearings, Alignment and Lubrication", "question": "Why should soft foot be corrected before final alignment?", "options": ["It eliminates thermal growth", "It replaces the coupling", "Tightening the feet can otherwise change machine position", "It permanently balances the rotor"], "answer": 2, "explanation": "Stable support is needed for repeatable alignment."}, {"id": 39, "category": "Bearings, Alignment and Lubrication", "question": "What does angular misalignment mean?", "options": ["Shafts are perfectly collinear", "Shaft centerlines are at an angle to each other", "The motor has low voltage", "Both shafts rotate too slowly"], "answer": 1, "explanation": "Angular misalignment is a directional difference between shaft axes."}, {"id": 40, "category": "Bearings, Alignment and Lubrication", "question": "What does parallel offset misalignment mean?", "options": ["The shafts have no radial displacement", "A pipe contains trapped air", "Parallel shaft centerlines are displaced from each other", "One bearing lacks grease only"], "answer": 2, "explanation": "Offset is the separation between otherwise parallel shaft axes."}, {"id": 41, "category": "Bearings, Alignment and Lubrication", "question": "Why may cold alignment targets differ from running alignment targets?", "options": ["Bearings eliminate expansion", "Couplings cannot transmit torque when cold", "Laser tools only work when hot", "Machines can move as they heat up"], "answer": 3, "explanation": "Thermal growth can shift shaft positions during operation."}, {"id": 42, "category": "Bearings, Alignment and Lubrication", "question": "A bearing suddenly becomes very hot with unusual noise. What is the appropriate response?", "options": ["Add unlimited grease while continuing at full load", "Ignore it until the next annual shutdown", "Remove the guard while it runs", "Assess the hazard and stop or escalate according to procedure"], "answer": 3, "explanation": "Abnormal heat and noise require prompt controlled investigation."}, {"id": 43, "category": "Bearings, Alignment and Lubrication", "question": "Where should force be applied when pressing a bearing onto a shaft?", "options": ["Only to the outer ring regardless of fit", "Only to the cage", "Through the rolling elements", "To the inner ring being fitted"], "answer": 3, "explanation": "Applying force to the fitted ring avoids loading the rolling elements."}, {"id": 44, "category": "Bearings, Alignment and Lubrication", "question": "What is a common sign of water contamination in some lubricating oils?", "options": ["A milky or cloudy appearance", "A guaranteed increase in purity", "A lower water-content test result", "A perfectly dry reservoir"], "answer": 0, "explanation": "Emulsified water can make oil cloudy; analysis confirms contamination."}, {"id": 45, "category": "Bearings, Alignment and Lubrication", "question": "Why are lubricant containers labeled and kept clean?", "options": ["Increase bearing preload", "Eliminate the need for oil analysis", "Prevent contamination and use of the wrong lubricant", "Change shaft speed"], "answer": 2, "explanation": "Controlled handling prevents cross-contamination and product mix-ups."}, {"id": 46, "category": "HVAC and Refrigeration", "question": "What does the evaporator do in a vapor-compression refrigeration cycle?", "options": ["Reject heat to outdoor air only", "Compress refrigerant vapor", "Store electrical energy", "Absorb heat from the cooled space or fluid"], "answer": 3, "explanation": "Refrigerant absorbs heat while evaporating at low pressure."}, {"id": 47, "category": "HVAC and Refrigeration", "question": "What does the condenser do?", "options": ["Meter oil into bearings", "Produce shaft power", "Reject heat from the refrigerant", "Reduce room humidity without cooling"], "answer": 2, "explanation": "The condenser rejects absorbed heat plus compressor input energy."}, {"id": 48, "category": "HVAC and Refrigeration", "question": "What is the compressor's main role?", "options": ["Drain condensate", "Raise refrigerant vapor pressure", "Filter room air", "Expand liquid to evaporator pressure"], "answer": 1, "explanation": "Compression raises vapor pressure and usually temperature."}, {"id": 49, "category": "HVAC and Refrigeration", "question": "What is the primary purpose of an expansion device?", "options": ["Compress low-pressure vapor", "Store chilled water", "Meter refrigerant and reduce its pressure", "Drive the condenser fan"], "answer": 2, "explanation": "The device creates a pressure drop before the evaporator."}, {"id": 50, "category": "HVAC and Refrigeration", "question": "What does refrigeration COP equal?", "options": ["Cooling output divided by work input", "Pressure divided by flow", "Work input divided by cooling output", "Cooling output multiplied by temperature"], "answer": 0, "explanation": "COP is a dimensionless measure of refrigeration efficiency."}, {"id": 51, "category": "HVAC and Refrigeration", "question": "A chiller delivers 300 kW of cooling using 75 kW of input power. What is its COP?", "options": ["375", "4", "225", "0.25"], "answer": 1, "explanation": "COP = 300/75 = 4."}, {"id": 52, "category": "HVAC and Refrigeration", "question": "What can a heavily clogged air filter cause?", "options": ["Lower filter pressure drop", "Reduced airflow and higher resistance", "Higher airflow with no extra power", "A guaranteed refrigerant leak"], "answer": 1, "explanation": "Dirt increases resistance through the filter."}, {"id": 53, "category": "HVAC and Refrigeration", "question": "Why are condenser coils cleaned?", "options": ["Raise fouling resistance", "Increase refrigerant contamination", "Eliminate compressor lubrication", "Maintain effective heat rejection"], "answer": 3, "explanation": "Dirty coils restrict airflow and heat transfer."}, {"id": 54, "category": "HVAC and Refrigeration", "question": "What does superheat mean?", "options": ["Liquid temperature below freezing", "Condenser pressure minus atmospheric pressure", "Vapor temperature above saturation temperature at its pressure", "Room temperature minus outdoor temperature"], "answer": 2, "explanation": "Superheat is referenced to the refrigerant saturation temperature at the measured pressure."}, {"id": 55, "category": "HVAC and Refrigeration", "question": "What does subcooling mean?", "options": ["Air temperature above the dew point only", "Cooling-water pressure drop", "Vapor temperature above saturation", "Liquid temperature below saturation temperature at its pressure"], "answer": 3, "explanation": "Subcooling indicates liquid refrigerant below its saturation temperature."}, {"id": 56, "category": "HVAC and Refrigeration", "question": "What is a cooling tower's main heat-rejection mechanism?", "options": ["Combustion of water", "Expansion of refrigerant in a compressor", "Evaporation of part of the circulating water", "Electrical resistance heating"], "answer": 2, "explanation": "Evaporation removes heat from the remaining circulating water."}, {"id": 57, "category": "HVAC and Refrigeration", "question": "Cooling-tower approach is normally the leaving water temperature minus what?", "options": ["Compressor discharge temperature", "Entering air dry-bulb temperature", "Chilled-water return temperature", "Entering air wet-bulb temperature"], "answer": 3, "explanation": "Approach compares cold-water temperature with entering air wet-bulb temperature."}, {"id": 58, "category": "HVAC and Refrigeration", "question": "What is the purpose of an AHU condensate drain?", "options": ["Supply compressor oil", "Meter refrigerant", "Increase duct pressure", "Remove water condensed from the air"], "answer": 3, "explanation": "Moisture condensing on a cooling coil must drain properly."}, {"id": 59, "category": "HVAC and Refrigeration", "question": "Which inspection is especially relevant after a dust storm at a Kuwait facility?", "options": ["Check outdoor coils and air filters for blockage", "Disable all fan guards", "Increase refrigerant charge without measurements", "Close all ventilation indefinitely"], "answer": 0, "explanation": "Dust can obstruct filters and outdoor heat-transfer surfaces."}, {"id": 60, "category": "HVAC and Refrigeration", "question": "A chilled-water coil cools poorly and its control valve is open. What is a useful first diagnostic check?", "options": ["Replace the entire chiller immediately", "Assume the thermostat is correct without checking", "Add refrigerant to the water loop", "Verify water flow, water temperatures and air conditions"], "answer": 3, "explanation": "Measurements help distinguish flow, airside and temperature problems."}, {"id": 61, "category": "Hydraulics and Pneumatics", "question": "What principle underlies a basic hydraulic press?", "options": ["Pressure disappears in enclosed fluids", "Pressure applied to a confined fluid is transmitted throughout it", "Force is independent of piston area", "Only gases transmit pressure"], "answer": 1, "explanation": "Pascal's principle relates transmitted pressure to force at each piston."}, {"id": 62, "category": "Hydraulics and Pneumatics", "question": "A hydraulic cylinder has area 0.01 m² at 5 MPa. What ideal force does it produce?", "options": ["500 kN", "500 N", "50 kN", "5 kN"], "answer": 2, "explanation": "F = pA = 5000000 × 0.01 = 50000 N, ignoring losses."}, {"id": 63, "category": "Hydraulics and Pneumatics", "question": "What mainly determines hydraulic cylinder speed for a given effective area?", "options": ["Fluid color", "Flow rate", "Reservoir paint", "Relief-valve label"], "answer": 1, "explanation": "Ideal cylinder speed equals flow divided by effective piston area."}, {"id": 64, "category": "Hydraulics and Pneumatics", "question": "What is the purpose of a hydraulic relief valve?", "options": ["Remove all oil particles", "Increase pressure without limit", "Limit excessive system pressure", "Measure piston travel"], "answer": 2, "explanation": "The valve opens at its setting to protect against overpressure."}, {"id": 65, "category": "Hydraulics and Pneumatics", "question": "What does a directional control valve control?", "options": ["The flow path and actuator direction", "Tank wall thickness", "Motor insulation resistance", "Oil chemistry"], "answer": 0, "explanation": "Routing flow determines actuator movement or holding states."}, {"id": 66, "category": "Hydraulics and Pneumatics", "question": "What is a hydraulic accumulator used for?", "options": ["Measure ambient humidity", "Store energy in pressurized fluid", "Eliminate all system leaks", "Remove the need for isolation"], "answer": 1, "explanation": "Accumulators store energy and can remain pressurized after shutdown."}, {"id": 67, "category": "Hydraulics and Pneumatics", "question": "Before opening an accumulator-connected hydraulic line, what is essential?", "options": ["Rely on the pump noise stopping", "Isolate and safely release stored pressure according to procedure", "Switch off only the room lights", "Loosen the fitting to check pressure by hand"], "answer": 1, "explanation": "Stopping a pump does not necessarily remove stored hydraulic energy."}, {"id": 68, "category": "Hydraulics and Pneumatics", "question": "How should a suspected high-pressure hydraulic leak be investigated?", "options": ["Use an approved safe method without placing skin near the leak", "Run a finger along the hose", "Hold the leak closed with a glove", "Tighten every fitting while pressurized"], "answer": 0, "explanation": "High-pressure fluid can penetrate skin; isolate before repair."}, {"id": 69, "category": "Hydraulics and Pneumatics", "question": "Why are hydraulic filters important?", "options": ["Replace pressure relief valves", "Cool oil to any required temperature", "Increase oil contamination", "Remove particles that damage close-clearance components"], "answer": 3, "explanation": "Cleanliness protects pumps, valves and actuators."}, {"id": 70, "category": "Hydraulics and Pneumatics", "question": "What can air entrained in hydraulic oil cause?", "options": ["Guaranteed higher efficiency", "Spongy movement, noise and erratic operation", "Perfectly rigid motion", "Zero compressibility"], "answer": 1, "explanation": "Air increases effective compressibility and can disrupt operation."}, {"id": 71, "category": "Hydraulics and Pneumatics", "question": "Compared with hydraulics, why is pneumatic positioning often less rigid?", "options": ["Compressed air cannot store energy", "Air has no mass", "Pneumatic cylinders have no seals", "Air is more compressible than hydraulic liquid"], "answer": 3, "explanation": "Gas compressibility allows more movement under changing load."}, {"id": 72, "category": "Hydraulics and Pneumatics", "question": "What does an air-line regulator control?", "options": ["Oil viscosity", "Motor frequency", "Pipe diameter", "Downstream air pressure"], "answer": 3, "explanation": "A regulator maintains a selected downstream pressure within its range."}, {"id": 73, "category": "Hydraulics and Pneumatics", "question": "Why is condensate drained from compressed-air receivers?", "options": ["Eliminate pressure inspections", "Prevent water accumulation and related corrosion or carryover", "Remove all oxygen", "Increase tank volume beyond its rating"], "answer": 1, "explanation": "Moisture condenses during compression and cooling."}, {"id": 74, "category": "Hydraulics and Pneumatics", "question": "What is the main purpose of an air dryer?", "options": ["Increase oil carryover", "Reduce moisture in compressed air", "Raise water content", "Measure shaft torque"], "answer": 1, "explanation": "Dryers reduce water vapor to a specified dew point."}, {"id": 75, "category": "Hydraulics and Pneumatics", "question": "A hydraulic cylinder drifts under load with its valve centered. What is a plausible cause?", "options": ["Low room lighting", "Internal leakage in the valve or cylinder", "Perfectly sealed components", "A larger reservoir label"], "answer": 1, "explanation": "Leakage can allow fluid movement and gradual actuator drift."}, {"id": 76, "category": "Heat Transfer and Thermodynamics", "question": "Which heat-transfer mode occurs through a stationary solid?", "options": ["Bulk convection only", "Conduction", "Mass filtration", "Evaporation only"], "answer": 1, "explanation": "Conduction transfers energy through molecular and electron interactions."}, {"id": 77, "category": "Heat Transfer and Thermodynamics", "question": "Which heat-transfer mode can occur across a vacuum?", "options": ["Liquid convection", "Radiation", "Advection", "Gas conduction only"], "answer": 1, "explanation": "Thermal radiation does not require a material medium."}, {"id": 78, "category": "Heat Transfer and Thermodynamics", "question": "What is forced convection?", "options": ["Heat transfer only in a vacuum", "Heat transfer without any fluid motion", "Heat transfer only through solids", "Heat transfer enhanced by externally driven fluid motion"], "answer": 3, "explanation": "Fans and pumps create fluid motion that supports forced convection."}, {"id": 79, "category": "Heat Transfer and Thermodynamics", "question": "What does the first law of thermodynamics express?", "options": ["Conservation of temperature", "Conservation of energy", "Zero entropy production in all processes", "Complete conversion of all heat to work in every cycle"], "answer": 1, "explanation": "Energy changes form but is conserved."}, {"id": 80, "category": "Heat Transfer and Thermodynamics", "question": "What is specific heat capacity?", "options": ["Energy per unit mass per degree of temperature change", "Power per unit speed", "Force per unit area", "Pressure per unit volume"], "answer": 0, "explanation": "Specific heat links sensible energy changes to mass and temperature change."}, {"id": 81, "category": "Heat Transfer and Thermodynamics", "question": "How much energy heats 2 kg of water by 10 K using cp = 4.2 kJ/(kg·K)?", "options": ["8.4 kJ", "84 kJ", "0.84 kJ", "840 kJ"], "answer": 1, "explanation": "Q = mcpΔT = 2 × 4.2 × 10 = 84 kJ."}, {"id": 82, "category": "Heat Transfer and Thermodynamics", "question": "What does heat-exchanger fouling generally do?", "options": ["Increases cleanliness", "Improves all operating conditions", "Eliminates pressure drop", "Adds thermal resistance and reduces heat transfer"], "answer": 3, "explanation": "Deposits impede heat flow and may also restrict fluid passages."}, {"id": 83, "category": "Heat Transfer and Thermodynamics", "question": "In a counterflow heat exchanger, how do the fluids move?", "options": ["Neither fluid moves", "Always in the same direction", "In opposite overall directions", "Only at right angles"], "answer": 2, "explanation": "Counterflow maintains useful temperature differences along the exchanger."}, {"id": 84, "category": "Heat Transfer and Thermodynamics", "question": "What does LMTD stand for?", "options": ["Logarithmic mean temperature difference", "Linear motor torque distribution", "Low mass thermal density", "Liquid maximum transport diameter"], "answer": 0, "explanation": "LMTD represents the effective temperature driving force for heat exchange."}, {"id": 85, "category": "Heat Transfer and Thermodynamics", "question": "What is latent heat?", "options": ["Mechanical friction alone", "Energy from temperature change only", "Stored electrical charge", "Energy associated with phase change at specified conditions"], "answer": 3, "explanation": "Latent heat accompanies phase change such as vaporization."}, {"id": 86, "category": "Heat Transfer and Thermodynamics", "question": "At the same pressure, what is saturated steam?", "options": ["Steam at the saturation temperature", "Steam below freezing", "Steam always at room temperature", "Steam containing no energy"], "answer": 0, "explanation": "Saturated steam is at the liquid-vapor phase-equilibrium temperature."}, {"id": 87, "category": "Heat Transfer and Thermodynamics", "question": "What is the main purpose of pipe insulation on a hot service line?", "options": ["Prevent all internal corrosion", "Replace pressure protection", "Increase heat loss", "Reduce heat loss and help control surface exposure"], "answer": 3, "explanation": "Insulation reduces heat flow; the full protection design still matters."}, {"id": 88, "category": "Heat Transfer and Thermodynamics", "question": "For steady incompressible flow, what does continuity require?", "options": ["Temperature must remain constant", "Velocity is independent of area", "Pressure is identical at every point", "Mass flow is conserved between sections without leaks"], "answer": 3, "explanation": "Mass conservation gives ρAV constant for a single flow path."}, {"id": 89, "category": "Heat Transfer and Thermodynamics", "question": "What is the ideal-gas equation?", "options": ["Q = UA only", "T = m/V", "pV = nRT", "p = Fv"], "answer": 2, "explanation": "The ideal-gas relation links absolute pressure, volume, amount and absolute temperature."}, {"id": 90, "category": "Heat Transfer and Thermodynamics", "question": "Why should absolute temperature be used in ideal-gas calculations?", "options": ["The relationship requires temperature measured from absolute zero", "Celsius is always identical to kelvin", "It makes pressure independent of volume", "It removes the gas constant"], "answer": 0, "explanation": "Kelvin is an absolute temperature scale."}, {"id": 91, "category": "Materials, Corrosion and Fabrication", "question": "What is general corrosion?", "options": ["A controlled welding technique", "Relatively widespread material loss over an exposed surface", "Only fracture without material loss", "A purely electrical measurement"], "answer": 1, "explanation": "General corrosion attacks a broad exposed area."}, {"id": 92, "category": "Materials, Corrosion and Fabrication", "question": "What conditions promote galvanic corrosion?", "options": ["Dissimilar metals electrically connected in an electrolyte", "A dry insulated metal pair without an electrolyte", "No conductive connection of any kind", "Identical dry plastics kept apart"], "answer": 0, "explanation": "Galvanic cells require a potential difference, electrical path and electrolyte."}, {"id": 93, "category": "Materials, Corrosion and Fabrication", "question": "What is pitting corrosion?", "options": ["A polishing process", "Localized corrosion producing small cavities", "Uniform elastic stretching", "A type of shaft alignment"], "answer": 1, "explanation": "Pitting creates concentrated local attack that may penetrate deeply."}, {"id": 94, "category": "Materials, Corrosion and Fabrication", "question": "Why can coastal exposure be challenging for equipment in Kuwait?", "options": ["Seawater is electrically nonconductive", "Salts and moisture can accelerate corrosion", "Humidity eliminates coatings", "Salt always prevents rust"], "answer": 1, "explanation": "Chloride-bearing moisture can increase corrosion risk."}, {"id": 95, "category": "Materials, Corrosion and Fabrication", "question": "What is the purpose of a protective coating?", "options": ["Increase electrolyte contact intentionally", "Replace all material selection", "Provide a barrier against the environment", "Make every metal stainless"], "answer": 2, "explanation": "A properly selected and applied coating separates metal from corrosive exposure."}, {"id": 96, "category": "Materials, Corrosion and Fabrication", "question": "What does cathodic protection aim to do?", "options": ["Increase oxygen content in all pipes", "Remove the need for inspection", "Make the protected metal the cathode of an electrochemical cell", "Make the protected metal dissolve faster"], "answer": 2, "explanation": "Sacrificial anodes or impressed current reduce corrosion of the protected structure."}, {"id": 97, "category": "Materials, Corrosion and Fabrication", "question": "Which nondestructive test is commonly used to measure remaining pipe-wall thickness?", "options": ["Torque testing", "Ultrasonic thickness testing", "Visual color matching only", "Airflow measurement"], "answer": 1, "explanation": "Ultrasonic transit time can determine wall thickness with proper calibration."}, {"id": 98, "category": "Materials, Corrosion and Fabrication", "question": "Which test is suitable for surface-breaking cracks in clean nonporous materials?", "options": ["Oil viscosity testing", "Vibration balancing", "Liquid penetrant testing", "Hydrostatic weighing"], "answer": 2, "explanation": "Penetrant enters surface-breaking defects and reveals them after development."}, {"id": 99, "category": "Materials, Corrosion and Fabrication", "question": "Magnetic particle testing requires which type of material?", "options": ["Any plastic", "Any glass", "All ceramics", "Ferromagnetic material"], "answer": 3, "explanation": "The method relies on magnetic flux leakage in ferromagnetic materials."}, {"id": 100, "category": "Materials, Corrosion and Fabrication", "question": "What does a weld procedure specification define?", "options": ["Only the welder's attendance", "Qualified instructions and variables for making a weld", "The building's air temperature history", "Only the pipe's paint color"], "answer": 1, "explanation": "A WPS controls welding variables needed for a suitable joint."}, {"id": 101, "category": "Materials, Corrosion and Fabrication", "question": "Why is surface preparation important before painting steel?", "options": ["It changes steel into stainless steel", "It guarantees unlimited coating life", "It improves coating adhesion and removes contamination", "It eliminates all future inspections"], "answer": 2, "explanation": "Contamination or poor surface condition can cause premature coating failure."}, {"id": 102, "category": "Materials, Corrosion and Fabrication", "question": "What is the main purpose of a gasket in a bolted flange?", "options": ["Measure pressure", "Transmit shaft torque", "Support a rotor", "Seal the joint between mating faces"], "answer": 3, "explanation": "Compressed gasket material fills small surface irregularities to limit leakage."}, {"id": 103, "category": "Materials, Corrosion and Fabrication", "question": "Why are flange bolts commonly tightened in a controlled cross pattern?", "options": ["Avoid using a specified torque", "Increase flange distortion", "Ensure one side is fully compressed first", "Promote even gasket compression"], "answer": 3, "explanation": "A staged cross pattern helps distribute load around the flange."}, {"id": 104, "category": "Materials, Corrosion and Fabrication", "question": "Why must a replacement gasket match the service conditions?", "options": ["Material suitability depends on temperature, pressure and fluid", "Only color affects sealing", "Thickness alone determines chemical compatibility", "All gaskets are interchangeable"], "answer": 0, "explanation": "Incorrect gasket materials can degrade or fail in service."}, {"id": 105, "category": "Materials, Corrosion and Fabrication", "question": "What is erosion in piping?", "options": ["A desired increase in wall thickness", "Material loss caused by mechanical action of moving fluid or particles", "A lubricant additive", "Only chemical reaction at rest"], "answer": 1, "explanation": "High velocities or entrained solids can wear away material."}, {"id": 106, "category": "Electrical and Instrumentation Awareness", "question": "What is the relationship between electrical power, voltage and current for a DC load?", "options": ["P = VI", "P = V/I", "P = I/V", "P = V + I"], "answer": 0, "explanation": "DC electrical power is voltage multiplied by current."}, {"id": 107, "category": "Electrical and Instrumentation Awareness", "question": "A DC device uses 24 V and 2 A. What power does it consume?", "options": ["12 W", "26 W", "48 W", "0.083 W"], "answer": 2, "explanation": "P = 24 × 2 = 48 W."}, {"id": 108, "category": "Electrical and Instrumentation Awareness", "question": "What is the purpose of protective earthing?", "options": ["Control pump flow", "Increase normal touch voltage", "Replace insulation in every circuit", "Provide a designed fault-current path that supports protective disconnection"], "answer": 3, "explanation": "Protective earthing is part of the electrical fault-protection system."}, {"id": 109, "category": "Electrical and Instrumentation Awareness", "question": "What does a motor overload protective device primarily respond to?", "options": ["Sustained excessive motor current or its thermal effect", "Water pH", "Room brightness", "Shaft paint thickness"], "answer": 0, "explanation": "Overload protection addresses excessive heating associated with overload."}, {"id": 110, "category": "Electrical and Instrumentation Awareness", "question": "What does a variable-frequency drive commonly control?", "options": ["Pipe wall thickness", "Lubricant acidity", "Tank corrosion rate directly", "AC motor speed by varying supply frequency"], "answer": 3, "explanation": "VFDs vary frequency and voltage to control suitable motors."}, {"id": 111, "category": "Electrical and Instrumentation Awareness", "question": "What does a 4–20 mA transmitter signal normally represent?", "options": ["Only an on/off light", "A fixed current of 20 mA at all times", "A measured process variable over a calibrated range", "Only electrical motor power"], "answer": 2, "explanation": "The current encodes a process value between calibrated endpoints."}, {"id": 112, "category": "Electrical and Instrumentation Awareness", "question": "A 4–20 mA pressure transmitter spans 0–10 bar. What pressure does 12 mA represent?", "options": ["5 bar", "10 bar", "3 bar", "7.5 bar"], "answer": 0, "explanation": "12 mA is halfway between 4 and 20 mA, so it represents half span."}, {"id": 113, "category": "Electrical and Instrumentation Awareness", "question": "Why is 4 mA used as a live zero in many loops?", "options": ["It helps distinguish zero measurement from some circuit faults", "It makes wire resistance infinite", "It means the sensor is always off", "It eliminates calibration"], "answer": 0, "explanation": "A zero process reading still has current; a broken loop may fall below the normal range."}, {"id": 114, "category": "Electrical and Instrumentation Awareness", "question": "What is an RTD used to measure?", "options": ["Vibration displacement only", "Temperature", "Pipe flow directly", "Torque"], "answer": 1, "explanation": "An RTD uses predictable changes in electrical resistance with temperature."}, {"id": 115, "category": "Electrical and Instrumentation Awareness", "question": "What does a thermocouple produce in response to a temperature difference?", "options": ["A small voltage", "A hydraulic pressure", "A fixed resistance of zero", "A large shaft torque"], "answer": 0, "explanation": "The thermoelectric effect generates a voltage related to junction temperatures."}, {"id": 116, "category": "Electrical and Instrumentation Awareness", "question": "What is instrument calibration?", "options": ["Cleaning only the display", "Comparing and, when needed, adjusting an instrument against a reference", "Changing units without checking accuracy", "Replacing every sensor annually"], "answer": 1, "explanation": "Calibration establishes the relationship between indications and reference values."}, {"id": 117, "category": "Electrical and Instrumentation Awareness", "question": "What is a control-loop setpoint?", "options": ["The oil change interval", "The maximum cable length", "The desired value of the controlled variable", "The sensor serial number"], "answer": 2, "explanation": "The controller acts to reduce deviation from the setpoint."}, {"id": 118, "category": "Electrical and Instrumentation Awareness", "question": "A motor repeatedly trips. What should a trainee supervisor do?", "options": ["Fit a larger breaker without assessment", "Restart repeatedly without investigation", "Arrange qualified diagnosis of load, supply and protection", "Bypass the overload device"], "answer": 2, "explanation": "Repeated trips indicate a fault or unsuitable operating condition requiring investigation."}, {"id": 119, "category": "Electrical and Instrumentation Awareness", "question": "Who should perform work inside an electrical panel?", "options": ["Only the newest employee", "Personnel qualified and authorized for that electrical work", "Any nearby mechanic without authorization", "Anyone wearing ordinary gloves"], "answer": 1, "explanation": "Electrical work requires the appropriate competence and authorization."}, {"id": 120, "category": "Electrical and Instrumentation Awareness", "question": "What does a normally closed contact mean?", "options": ["It can never open", "It is closed in its defined unactuated state", "It is closed only after overload", "It is always electrically isolated"], "answer": 1, "explanation": "Normal describes the reference state before actuation, as defined for the device."}, {"id": 121, "category": "Safety and Work Control", "question": "What is the main purpose of lockout/tagout during maintenance?", "options": ["Prevent unexpected energization and hazardous energy release", "Replace all training", "Track spare-part prices", "Increase machine output"], "answer": 0, "explanation": "Energy control protects workers during servicing."}, {"id": 122, "category": "Safety and Work Control", "question": "Is pressing a stop button normally sufficient energy isolation for maintenance?", "options": ["No, energy sources and stored energy must be controlled", "Yes, if the indicator is dark", "Yes, if production is busy", "Yes, for every machine"], "answer": 0, "explanation": "A control command alone is not physical isolation of hazardous energy."}, {"id": 123, "category": "Safety and Work Control", "question": "What must follow isolation before work starts under an energy-control procedure?", "options": ["Immediate removal of guards without checks", "Verification that hazardous energy is effectively controlled", "Restarting production", "Removing other workers' locks"], "answer": 1, "explanation": "Verification confirms that the isolation has achieved the intended safe state."}, {"id": 124, "category": "Safety and Work Control", "question": "Which is an example of stored mechanical energy?", "options": ["A disconnected label printer with no stored energy", "A written work order", "An empty cardboard box", "A compressed spring"], "answer": 3, "explanation": "Compressed springs can release energy even when the main drive is stopped."}, {"id": 125, "category": "Safety and Work Control", "question": "What should a trainee do when asked to bypass a safety interlock to save time?", "options": ["Stop and escalate through the authorized safety process", "Bypass it without documentation", "Ask an untrained worker to bypass it", "Cover its warning label"], "answer": 0, "explanation": "Safety functions must not be defeated through an informal shortcut."}, {"id": 126, "category": "Safety and Work Control", "question": "What is the purpose of a permit-to-work system?", "options": ["Remove the need for isolation", "Control defined hazardous work through authorization and precautions", "Replace practical risk assessment", "Guarantee that no hazard exists"], "answer": 1, "explanation": "Permits coordinate work, responsibilities and required safety controls."}, {"id": 127, "category": "Safety and Work Control", "question": "Before entering a permit-required confined space, what is needed?", "options": ["Only a handheld flashlight", "Only an open hatch", "The authorized entry process, atmospheric assessment and rescue arrangements", "Only a verbal promise from a colleague"], "answer": 2, "explanation": "Entry must follow the applicable confined-space control procedure."}, {"id": 128, "category": "Safety and Work Control", "question": "A person collapses inside a confined space. What should an untrained bystander do?", "options": ["Enter immediately without equipment", "Hold their breath and enter", "Send another untrained person inside", "Raise the alarm and activate the planned rescue response without entering"], "answer": 3, "explanation": "Unplanned entry can create additional casualties; trained rescue is required."}, {"id": 129, "category": "Safety and Work Control", "question": "What is a job safety analysis intended to do?", "options": ["Rank staff salaries", "Identify task steps, hazards and controls", "Replace equipment manuals", "Measure only repair speed"], "answer": 1, "explanation": "Breaking a task into steps helps identify and control its hazards."}, {"id": 130, "category": "Safety and Work Control", "question": "What should happen if actual job conditions differ materially from the permit?", "options": ["Change the permit secretly", "Continue because a permit exists", "Ignore the new hazard", "Stop and have the work reassessed and reauthorized"], "answer": 3, "explanation": "Changed conditions can invalidate the original controls."}, {"id": 131, "category": "Safety and Work Control", "question": "Which lifting practice is appropriate?", "options": ["Exceed sling rating briefly", "Stand beneath a suspended load", "Use inspected, suitably rated gear and a planned lift", "Use an unmarked damaged sling"], "answer": 2, "explanation": "Lifting equipment and methods must suit the load and lift conditions."}, {"id": 132, "category": "Safety and Work Control", "question": "Why is housekeeping important in a workshop?", "options": ["It reduces slip, trip and access hazards", "It changes equipment capacity", "It replaces machine guarding", "It eliminates electrical faults"], "answer": 0, "explanation": "Clear, orderly work areas reduce preventable hazards."}, {"id": 133, "category": "Safety and Work Control", "question": "What should a supervisor do after a near miss?", "options": ["Report it and investigate contributing factors", "Wait for an injury before acting", "Hide it because no injury occurred", "Blame someone without evidence"], "answer": 0, "explanation": "Near misses provide opportunities to prevent future incidents."}, {"id": 134, "category": "Safety and Work Control", "question": "What is the preferred direction in the hierarchy of controls?", "options": ["Use PPE as the only possible control", "Eliminate or reduce hazards at source before relying only on PPE", "Ignore engineering controls", "Start with warning signs in every case"], "answer": 1, "explanation": "Elimination, substitution and engineering controls generally precede administrative controls and PPE."}, {"id": 135, "category": "Safety and Work Control", "question": "During hot outdoor maintenance in Kuwait, what should planning consider?", "options": ["Heat exposure controls, suitable rest arrangements and worker condition", "Only job speed", "Scheduling all heavy work at the hottest time", "Removing drinking water"], "answer": 0, "explanation": "Heat risk needs a task-specific plan and monitoring under applicable site requirements."}, {"id": 136, "category": "Maintenance Strategies and Reliability", "question": "What is preventive maintenance?", "options": ["Maintenance without records", "Only repair after complete failure", "Only emergency work", "Maintenance performed at planned intervals or usage limits"], "answer": 3, "explanation": "Preventive tasks are scheduled to reduce the likelihood of failure."}, {"id": 137, "category": "Maintenance Strategies and Reliability", "question": "What is predictive maintenance based on?", "options": ["Condition information used to anticipate maintenance needs", "Ignoring equipment trends", "Random replacement dates only", "Supplier advertising only"], "answer": 0, "explanation": "Condition indicators help identify developing degradation."}, {"id": 138, "category": "Maintenance Strategies and Reliability", "question": "What is corrective maintenance?", "options": ["Work to restore an item after a fault is identified", "Only buying new equipment", "Only cleaning before any defect exists", "Only writing a budget"], "answer": 0, "explanation": "Corrective maintenance addresses an identified failure or defect."}, {"id": 139, "category": "Maintenance Strategies and Reliability", "question": "When can run-to-failure be a reasonable strategy?", "options": ["For every safety-critical device", "For suitable low-consequence items after risk and cost assessment", "For all high-risk pressure vessels", "Whenever spares are unavailable"], "answer": 1, "explanation": "The strategy may suit inexpensive noncritical items with acceptable failure consequences."}, {"id": 140, "category": "Maintenance Strategies and Reliability", "question": "What does MTBF stand for?", "options": ["Mean time between failures", "Maximum torque before fracture", "Minimum temperature before freezing", "Monthly task budget forecast"], "answer": 0, "explanation": "MTBF is a reliability metric for repairable equipment."}, {"id": 141, "category": "Maintenance Strategies and Reliability", "question": "A repairable asset runs 1200 operating hours and has 4 failures. What is the simple estimated MTBF?", "options": ["0.0033 hours", "300 hours", "1204 hours", "4800 hours"], "answer": 1, "explanation": "Estimated MTBF = total operating time / number of failures."}, {"id": 142, "category": "Maintenance Strategies and Reliability", "question": "What does MTTR commonly mean in maintenance reporting?", "options": ["Minimum torque to rotate", "Monthly total test records", "Maximum temperature to run", "Mean time to repair"], "answer": 3, "explanation": "MTTR should be defined consistently, including which repair intervals are counted."}, {"id": 143, "category": "Maintenance Strategies and Reliability", "question": "Four repairs take 2, 3, 4 and 7 hours. What is their mean repair time?", "options": ["16 hours", "3 hours", "7 hours", "4 hours"], "answer": 3, "explanation": "The total is 16 hours for four repairs, giving 4 hours per repair."}, {"id": 144, "category": "Maintenance Strategies and Reliability", "question": "Using A = MTBF/(MTBF + MTTR), what availability results from 90 h MTBF and 10 h MTTR?", "options": ["10%", "90%", "81%", "100%"], "answer": 1, "explanation": "90/(90 + 10) = 0.90 under the stated simple availability model."}, {"id": 145, "category": "Maintenance Strategies and Reliability", "question": "What is the purpose of an FMEA?", "options": ["Replace every asset", "Identify failure modes, effects and priorities for risk reduction", "Eliminate all failures automatically", "Calculate only wages"], "answer": 1, "explanation": "Failure mode and effects analysis supports systematic risk assessment."}, {"id": 146, "category": "Maintenance Strategies and Reliability", "question": "What does root cause analysis seek?", "options": ["Underlying causes that can be addressed to prevent recurrence", "A quick conclusion without evidence", "Only the visible damaged part", "The first person to blame"], "answer": 0, "explanation": "Effective analysis looks beyond symptoms and tests causal explanations."}, {"id": 147, "category": "Maintenance Strategies and Reliability", "question": "What is a bad actor asset?", "options": ["Any asset painted red", "An asset with repeated or disproportionate reliability problems", "Every standby pump", "The newest item in stores"], "answer": 1, "explanation": "Bad actors consume excessive maintenance effort or cause repeated losses."}, {"id": 148, "category": "Maintenance Strategies and Reliability", "question": "Why should condition data be trended over time?", "options": ["Changes can reveal degradation before a limit is exceeded", "Trending repairs the machine", "Trends eliminate calibration", "A single reading is always useless"], "answer": 0, "explanation": "Comparable historical data helps distinguish normal behavior from deterioration."}, {"id": 149, "category": "Maintenance Strategies and Reliability", "question": "What is reliability-centered maintenance focused on?", "options": ["Replacing all parts at equal intervals", "Choosing only the cheapest lubricant", "Maximizing paperwork", "Selecting maintenance based on functions, failures and consequences"], "answer": 3, "explanation": "RCM links maintenance choices to functional failure risks and effectiveness."}, {"id": 150, "category": "Maintenance Strategies and Reliability", "question": "Why record the actual failure mode on a work order?", "options": ["To replace asset identification", "Only to increase page count", "Support analysis and better future maintenance decisions", "To avoid documenting repairs"], "answer": 2, "explanation": "Consistent failure data supports targeted improvement."}, {"id": 151, "category": "Planning, CMMS and Spare Parts", "question": "What is the purpose of a work order?", "options": ["Guarantee spare availability", "Authorize and document a defined maintenance task", "Serve only as a purchase invoice", "Replace the equipment nameplate"], "answer": 1, "explanation": "A work order captures scope, resources, execution and completion information."}, {"id": 152, "category": "Planning, CMMS and Spare Parts", "question": "What does CMMS stand for?", "options": ["Certified material manufacturing service", "Cooling machine measurement standard", "Central mechanical motor speed", "Computerized maintenance management system"], "answer": 3, "explanation": "A CMMS organizes maintenance assets, tasks and records."}, {"id": 153, "category": "Planning, CMMS and Spare Parts", "question": "What should a job plan normally include?", "options": ["Only the equipment color", "Only a completion date", "Only the technician's first name", "Scope, steps, resources, safety requirements and acceptance criteria"], "answer": 3, "explanation": "Good plans make work executable and verifiable."}, {"id": 154, "category": "Planning, CMMS and Spare Parts", "question": "What distinguishes scheduling from planning?", "options": ["Scheduling assigns timing and resources to prepared work", "They never relate to one another", "Scheduling identifies material chemistry only", "Planning only measures attendance"], "answer": 0, "explanation": "Planning defines how to do the work; scheduling arranges when and by whom."}, {"id": 155, "category": "Planning, CMMS and Spare Parts", "question": "How should maintenance backlog be interpreted?", "options": ["Only completed tasks", "Outstanding work assessed by priority and available capacity", "Proof that every team is inefficient", "All work is equally urgent"], "answer": 1, "explanation": "Backlog needs context such as risk, readiness and labor capacity."}, {"id": 156, "category": "Planning, CMMS and Spare Parts", "question": "A backlog contains 240 labor-hours and a crew has 80 available labor-hours per week. How many crew-weeks is it?", "options": ["3", "320", "160", "0.33"], "answer": 0, "explanation": "Backlog weeks = 240/80 = 3, assuming the stated available capacity."}, {"id": 157, "category": "Planning, CMMS and Spare Parts", "question": "What should determine work-order priority?", "options": ["Safety, service impact, asset criticality and urgency", "Who complains loudest only", "Paint condition only", "Alphabetical equipment name"], "answer": 0, "explanation": "Priority should reflect consequences and the need for timely action."}, {"id": 158, "category": "Planning, CMMS and Spare Parts", "question": "Why identify an asset with a unique tag?", "options": ["Increase motor speed", "Reduce fluid viscosity", "Link its history, documents and work accurately", "Replace its serial number physically"], "answer": 2, "explanation": "Unique identification prevents records from being assigned to the wrong asset."}, {"id": 159, "category": "Planning, CMMS and Spare Parts", "question": "What is a bill of materials for an asset?", "options": ["A list of employee leave dates", "Only the asset purchase price", "A daily temperature graph", "A structured list of relevant components and spare parts"], "answer": 3, "explanation": "An asset BOM supports accurate parts identification and planning."}, {"id": 160, "category": "Planning, CMMS and Spare Parts", "question": "What is a critical spare?", "options": ["Any spare with bright packaging", "A spare whose absence can cause significant unacceptable downtime or risk", "Every office supply", "Only the cheapest spare"], "answer": 1, "explanation": "Criticality depends on consequences, alternatives and replenishment time."}, {"id": 161, "category": "Planning, CMMS and Spare Parts", "question": "What is lead time in spare-parts procurement?", "options": ["The motor acceleration time", "The mass of lead in the part", "The technician's break duration", "Time from ordering to availability for use"], "answer": 3, "explanation": "Lead time includes relevant procurement and delivery stages."}, {"id": 162, "category": "Planning, CMMS and Spare Parts", "question": "With demand of 2 units/day, lead time of 10 days and safety stock of 5, what is the simple reorder point?", "options": ["15 units", "7 units", "20 units", "25 units"], "answer": 3, "explanation": "Reorder point = lead-time demand + safety stock = 2 × 10 + 5."}, {"id": 163, "category": "Planning, CMMS and Spare Parts", "question": "What is the purpose of safety stock?", "options": ["Buffer uncertainty in demand or replenishment", "Eliminate all inventory costs", "Store only obsolete items", "Replace incoming inspection"], "answer": 0, "explanation": "Safety stock reduces stockout risk under variability."}, {"id": 164, "category": "Planning, CMMS and Spare Parts", "question": "What should be checked when receiving a replacement bearing?", "options": ["Only delivery vehicle type", "Only box weight", "Only package color", "Part designation, specification, condition and traceability"], "answer": 3, "explanation": "Verification reduces the chance of installing the wrong or damaged part."}, {"id": 165, "category": "Planning, CMMS and Spare Parts", "question": "When should a work order be closed?", "options": ["As soon as a technician is assigned", "Whenever the calendar month ends", "After work, verification and required records are complete", "Before materials arrive"], "answer": 2, "explanation": "Closure should reflect completed and accepted work with accurate records."}, {"id": 166, "category": "Supervision and Communication", "question": "What is a trainee supervisor's best response to a task beyond their competence?", "options": ["Seek guidance and appropriate authorization", "Assign it to another untrained trainee", "Hide uncertainty from everyone", "Guess and proceed alone"], "answer": 0, "explanation": "Recognizing limits and escalating protects people and equipment."}, {"id": 167, "category": "Supervision and Communication", "question": "What should a shift handover communicate?", "options": ["Only personal opinions", "Only yesterday's weather", "Equipment status, ongoing work, isolations and outstanding risks", "Only total staff count"], "answer": 2, "explanation": "A structured handover preserves operational continuity."}, {"id": 168, "category": "Supervision and Communication", "question": "Why hold a toolbox talk before a maintenance task?", "options": ["Guarantee zero risk without controls", "Avoid questions from technicians", "Replace every permit", "Align the team on the job, hazards and responsibilities"], "answer": 3, "explanation": "A focused briefing helps workers understand the task and controls."}, {"id": 169, "category": "Supervision and Communication", "question": "Two technicians disagree about a repair method. What should the supervisor do?", "options": ["Allow both conflicting methods simultaneously", "Choose whoever speaks louder", "Review the approved procedure and technical evidence with them", "Ignore the dispute"], "answer": 2, "explanation": "Technical decisions should be based on requirements, competence and evidence."}, {"id": 170, "category": "Supervision and Communication", "question": "How should a supervisor delegate a task?", "options": ["Choose randomly regardless of training", "Avoid follow-up entirely", "Match competence to the task and explain scope, controls and expectations", "Give only a deadline"], "answer": 2, "explanation": "Effective delegation includes clear responsibilities and suitable oversight."}, {"id": 171, "category": "Supervision and Communication", "question": "An operator reports a new intermittent noise. What is the best response?", "options": ["Tell the operator to stop reporting", "Dismiss it because the machine still runs", "Replace every component immediately", "Record the conditions and arrange a proportionate investigation"], "answer": 3, "explanation": "Operating context helps diagnose intermittent defects."}, {"id": 172, "category": "Supervision and Communication", "question": "What makes a useful maintenance report?", "options": ["Only technical abbreviations without context", "Unsupported accusations", "A completion claim with no evidence", "Clear facts, measurements, actions and outstanding items"], "answer": 3, "explanation": "Useful records let others understand the condition and work performed."}, {"id": 173, "category": "Supervision and Communication", "question": "A contractor arrives for hazardous work. What should be verified first?", "options": ["Only their uniform color", "Only their vehicle registration", "Whether they can finish without a permit", "Scope, competence, induction and required work controls"], "answer": 3, "explanation": "Contractors need coordination and the same applicable site controls."}, {"id": 174, "category": "Supervision and Communication", "question": "How should a trainee handle an unclear instruction?", "options": ["Assume the most hazardous interpretation", "Pretend to understand", "Pass the uncertainty to an untrained worker", "Clarify it before proceeding with uncertain work"], "answer": 3, "explanation": "Clarification prevents errors and mismatched expectations."}, {"id": 175, "category": "Supervision and Communication", "question": "Production asks to return equipment early before safety checks are complete. What is appropriate?", "options": ["Remove the fault record", "Release it without checks", "Explain the remaining checks and escalate the schedule conflict", "Sign completion in advance"], "answer": 2, "explanation": "Return-to-service requirements must be satisfied despite time pressure."}, {"id": 176, "category": "Supervision and Communication", "question": "What is constructive feedback?", "options": ["A vague complaint with no example", "Specific, respectful guidance focused on behavior and improvement", "Avoiding every difficult discussion", "Public humiliation"], "answer": 1, "explanation": "Effective feedback states what happened and how to improve."}, {"id": 177, "category": "Supervision and Communication", "question": "Why should supervisors encourage hazard reporting?", "options": ["It eliminates the supervisor's responsibility", "It proves no inspection is needed", "It should be used only to assign blame", "Workers often identify changing conditions early"], "answer": 3, "explanation": "Open reporting supports timely action on real risks."}, {"id": 178, "category": "Supervision and Communication", "question": "How should conflicting maintenance requests be communicated?", "options": ["Explain risk-based priorities and expected timing to stakeholders", "Promise every request immediate completion", "Prioritize by personal friendship", "Hide resource limitations"], "answer": 0, "explanation": "Transparent priorities help align operations and maintenance."}, {"id": 179, "category": "Supervision and Communication", "question": "A repair is delayed because a required part is unavailable. What should be reported?", "options": ["A false completion date", "Only that someone failed", "No information until the next month", "The cause, impact, options and revised estimate"], "answer": 3, "explanation": "Clear escalation allows informed operational decisions."}, {"id": 180, "category": "Supervision and Communication", "question": "What demonstrates professional integrity in maintenance records?", "options": ["Deleting unfavorable failure data", "Copying last month's measurements", "Signing for inspections not performed", "Recording actual findings and work honestly"], "answer": 3, "explanation": "Accurate records are essential for trust and engineering decisions."}, {"id": 181, "category": "Troubleshooting and Condition Monitoring", "question": "What is a sound first step in systematic troubleshooting?", "options": ["Define the symptom and gather operating information", "Replace the most expensive part", "Change several settings randomly", "Assume the previous fault has returned"], "answer": 0, "explanation": "A clear problem statement guides useful measurements."}, {"id": 182, "category": "Troubleshooting and Condition Monitoring", "question": "Why compare measurements with a baseline?", "options": ["Replace operating limits", "Identify meaningful deviation from known operating behavior", "Avoid using instruments", "Prove every change is a fault"], "answer": 1, "explanation": "Comparable baselines help interpret current condition."}, {"id": 183, "category": "Troubleshooting and Condition Monitoring", "question": "Why change one diagnostic variable at a time when practical?", "options": ["Make diagnosis slower for its own sake", "Avoid recording results", "Guarantee that no fault can recur", "Help identify cause and effect"], "answer": 3, "explanation": "Controlled changes reduce ambiguity in interpreting outcomes."}, {"id": 184, "category": "Troubleshooting and Condition Monitoring", "question": "Which technique is useful for detecting abnormal bearing or rotor behavior while operating?", "options": ["Room illumination measurement", "Paint thickness measurement only", "Water hardness testing", "Vibration analysis"], "answer": 3, "explanation": "Vibration characteristics can indicate developing mechanical issues."}, {"id": 185, "category": "Troubleshooting and Condition Monitoring", "question": "A strong vibration component at shaft rotational frequency may suggest what?", "options": ["Zero rotating mass", "Perfect alignment", "A guaranteed broken gear tooth in every case", "Rotor unbalance, requiring further diagnosis"], "answer": 3, "explanation": "Unbalance often produces rotational-frequency vibration, but confirmation needs context."}, {"id": 186, "category": "Troubleshooting and Condition Monitoring", "question": "Why is vibration amplitude alone insufficient for a full diagnosis?", "options": ["Only the instrument color matters", "Amplitude has no use", "Every fault has the same spectrum", "Frequency, direction, operating state and history also matter"], "answer": 3, "explanation": "Different faults and conditions can produce similar overall levels."}, {"id": 187, "category": "Troubleshooting and Condition Monitoring", "question": "What is infrared thermography useful for?", "options": ["Replacing all electrical isolation", "Determining exact metal chemistry", "Finding abnormal surface-temperature patterns", "Measuring internal pressure directly"], "answer": 2, "explanation": "Thermal patterns can reveal hot spots, subject to emissivity and viewing conditions."}, {"id": 188, "category": "Troubleshooting and Condition Monitoring", "question": "Why does emissivity matter in infrared measurements?", "options": ["It affects the relationship between emitted radiation and indicated temperature", "It determines motor frequency", "It replaces focus and calibration", "It changes fluid density directly"], "answer": 0, "explanation": "Incorrect emissivity assumptions can distort temperature readings."}, {"id": 189, "category": "Troubleshooting and Condition Monitoring", "question": "What can oil analysis help detect?", "options": ["Wear debris, contamination and lubricant degradation", "Every crack in every component", "Motor winding voltage directly", "Exact shaft alignment without other data"], "answer": 0, "explanation": "Oil condition and debris can reveal lubrication and wear problems."}, {"id": 190, "category": "Troubleshooting and Condition Monitoring", "question": "Why should oil samples be collected consistently from a representative point?", "options": ["Eliminate the need for labels", "Improve comparability and avoid misleading contamination", "Increase machine load", "Make the oil darker"], "answer": 1, "explanation": "Sampling quality strongly affects the usefulness of analysis."}, {"id": 191, "category": "Troubleshooting and Condition Monitoring", "question": "A belt drive slips under load. What should be checked?", "options": ["Only the nameplate font", "Only room humidity", "Belt condition, tension, alignment and loading", "Only motor paint"], "answer": 2, "explanation": "Slippage can result from inadequate tension, wear, contamination or excessive load."}, {"id": 192, "category": "Troubleshooting and Condition Monitoring", "question": "What may water hammer in a liquid pipeline result from?", "options": ["Perfectly steady flow with no disturbance", "A rapid change in flow velocity", "Low pipe paint thickness", "A slowly moving thermometer"], "answer": 1, "explanation": "Rapid flow changes create pressure waves in the pipeline."}, {"id": 193, "category": "Troubleshooting and Condition Monitoring", "question": "A heat exchanger loses performance gradually. Which combination is useful to review?", "options": ["Only room noise", "Only external color", "Only its purchase date", "Inlet/outlet temperatures, flow and pressure drop"], "answer": 3, "explanation": "Thermal and hydraulic data help distinguish fouling and flow problems."}, {"id": 194, "category": "Troubleshooting and Condition Monitoring", "question": "What should happen after correcting a fault?", "options": ["Close the job without testing", "Discard all measurements", "Assume every similar asset has the same fault", "Verify normal operation and document the repair"], "answer": 3, "explanation": "Verification checks that the intended function has been restored."}, {"id": 195, "category": "Troubleshooting and Condition Monitoring", "question": "A fault recurs after several identical repairs. What is the best next step?", "options": ["Stop recording the failures", "Repeat the same repair indefinitely without review", "Review failure evidence and investigate underlying causes", "Blame the newest technician automatically"], "answer": 2, "explanation": "Recurrence suggests unresolved causes or an ineffective repair strategy."}, {"id": 196, "category": "Facilities, Utilities and Environmental Care", "question": "What is a standby generator intended to provide?", "options": ["Unlimited power without fuel", "Electrical power when the normal supply is unavailable", "Cooling without heat rejection", "Compressed air only"], "answer": 1, "explanation": "Standby generation supports designated loads during supply loss."}, {"id": 197, "category": "Facilities, Utilities and Environmental Care", "question": "Why are standby systems periodically tested under an approved plan?", "options": ["Use up all stored fuel", "Confirm readiness and detect hidden failures", "Replace operating records", "Guarantee they never need maintenance"], "answer": 1, "explanation": "Unused equipment can develop faults that remain hidden until demand."}, {"id": 198, "category": "Facilities, Utilities and Environmental Care", "question": "What is the purpose of an automatic transfer switch?", "options": ["Measure exhaust emissions only", "Control cooling-tower chemistry", "Transfer a load between designated power sources", "Regulate hydraulic oil level"], "answer": 2, "explanation": "An ATS manages source transfer according to its control logic and design."}, {"id": 199, "category": "Facilities, Utilities and Environmental Care", "question": "Why is a generator cooling system important?", "options": ["Increase fuel contamination", "Replace exhaust ventilation", "Prevent excessive engine temperature", "Eliminate the need for lubrication"], "answer": 2, "explanation": "Combustion engines require heat rejection to stay within operating limits."}, {"id": 200, "category": "Facilities, Utilities and Environmental Care", "question": "What is the main purpose of a steam trap?", "options": ["Add oil to steam", "Discharge condensate while limiting live-steam loss", "Measure electrical resistance", "Raise boiler pressure without limit"], "answer": 1, "explanation": "A functioning trap removes condensate and often noncondensable gases."}, {"id": 201, "category": "Facilities, Utilities and Environmental Care", "question": "What may a failed-open steam trap cause?", "options": ["Guaranteed zero energy loss", "Improved efficiency in every case", "No condensate movement anywhere", "Loss of live steam and wasted energy"], "answer": 3, "explanation": "A trap stuck open can pass steam unnecessarily."}, {"id": 202, "category": "Facilities, Utilities and Environmental Care", "question": "Why are compressed-air leaks repaired?", "options": ["Reduce wasted energy and maintain useful system capacity", "Avoid all pressure measurement", "Increase compressor running time intentionally", "Raise moisture content"], "answer": 0, "explanation": "Leaks consume compressed air that required energy to produce."}, {"id": 203, "category": "Facilities, Utilities and Environmental Care", "question": "What is the purpose of a pressure-reducing valve in a water system?", "options": ["Control downstream pressure within its operating range", "Measure tank level only", "Increase pressure above supply without energy input", "Remove every dissolved salt"], "answer": 0, "explanation": "The valve throttles flow to regulate downstream pressure."}, {"id": 204, "category": "Facilities, Utilities and Environmental Care", "question": "What does a strainer do in a water line?", "options": ["Remove every dissolved mineral", "Capture debris larger than its openings", "Sterilize all water", "Increase pipe bore"], "answer": 1, "explanation": "Strainers trap particles according to their mesh or perforation size."}, {"id": 205, "category": "Facilities, Utilities and Environmental Care", "question": "Why should used oil be collected in appropriate labeled containers?", "options": ["Mix it with drinking water", "Support controlled handling and proper disposal or recycling", "Eliminate all spill controls", "Allow discharge into storm drains"], "answer": 1, "explanation": "Used oil needs suitable containment and an approved waste route."}, {"id": 206, "category": "Facilities, Utilities and Environmental Care", "question": "What is the appropriate first response to an oil spill when safe to act?", "options": ["Wash it into a drain", "Ignore a small spill in a walkway", "Use an ignition source to remove it", "Raise the alarm and follow the spill-control procedure"], "answer": 3, "explanation": "Site procedures guide safe isolation, containment and cleanup."}, {"id": 207, "category": "Facilities, Utilities and Environmental Care", "question": "Why should equipment exhaust and ventilation openings remain unobstructed?", "options": ["Avoid routine inspection", "Reduce all cooling capacity", "Increase room contamination", "Maintain designed airflow and prevent harmful buildup or overheating"], "answer": 3, "explanation": "Blocked airflow can compromise ventilation and equipment operation."}, {"id": 208, "category": "Facilities, Utilities and Environmental Care", "question": "What should maintenance do if a potable-water connection may be contaminated?", "options": ["Declare it safe without testing", "Mask the odor with chemicals", "Connect it to an unverified supply", "Isolate or restrict use as authorized and escalate for assessment"], "answer": 3, "explanation": "Potential contamination requires controlled assessment and restoration."}, {"id": 209, "category": "Facilities, Utilities and Environmental Care", "question": "What is lifecycle cost in equipment selection?", "options": ["First delivery cost only", "Purchase price only", "One month's labor cost", "Purchase, operation, maintenance and disposal costs over its life"], "answer": 3, "explanation": "Lifecycle costing accounts for costs beyond acquisition."}, {"id": 210, "category": "Facilities, Utilities and Environmental Care", "question": "Why consider dust, heat and coastal exposure in a Kuwait maintenance plan?", "options": ["They affect only office furniture", "They can influence filtration, cooling, corrosion and inspection needs", "They make manufacturer instructions unnecessary", "They remove all need for lubrication"], "answer": 1, "explanation": "Local operating conditions should inform maintenance within equipment requirements."}, {"id": 211, "category": "Applied Calculations and Practical Decisions", "question": "A shaft turns at 600 rpm. What is its rotational frequency?", "options": ["0.1 Hz", "10 Hz", "60 Hz", "600 Hz"], "answer": 1, "explanation": "600 revolutions per minute divided by 60 equals 10 revolutions per second."}, {"id": 212, "category": "Applied Calculations and Practical Decisions", "question": "A motor produces 10 N·m at 1500 rpm. What is the approximate shaft power?", "options": ["0.157 kW", "15.7 kW", "150 kW", "1.57 kW"], "answer": 3, "explanation": "P = T × 2πN/60 = 10 × 2π × 1500/60 W."}, {"id": 213, "category": "Applied Calculations and Practical Decisions", "question": "A machine consumes 5 kW for 8 hours. How much energy is used?", "options": ["400 kWh", "13 kWh", "40 kWh", "0.625 kWh"], "answer": 2, "explanation": "Energy = power × time = 5 × 8."}, {"id": 214, "category": "Applied Calculations and Practical Decisions", "question": "A flow of 3 m³/h equals approximately how many liters per minute?", "options": ["3000 L/min", "5 L/min", "50 L/min", "180 L/min"], "answer": 2, "explanation": "3000 liters per hour divided by 60 gives 50 L/min."}, {"id": 215, "category": "Applied Calculations and Practical Decisions", "question": "What pressure is equivalent to 2 bar?", "options": ["200 kPa", "2000 kPa", "20 kPa", "2 kPa"], "answer": 0, "explanation": "1 bar = 100 kPa, so 2 bar = 200 kPa."}, {"id": 216, "category": "Applied Calculations and Practical Decisions", "question": "A tank has a constant area of 2 m² and its water level rises 0.5 m. What volume is added?", "options": ["1 m³", "4 m³", "0.25 m³", "2.5 m³"], "answer": 0, "explanation": "Volume change = area × level change = 2 × 0.5."}, {"id": 217, "category": "Applied Calculations and Practical Decisions", "question": "Water flows at 0.02 m³/s through an area of 0.01 m². What is mean velocity?", "options": ["2 m/s", "20 m/s", "0.5 m/s", "0.0002 m/s"], "answer": 0, "explanation": "v = Q/A = 0.02/0.01."}, {"id": 218, "category": "Applied Calculations and Practical Decisions", "question": "A pump delivers 8 kW of hydraulic power using 10 kW of shaft power. What is pump efficiency?", "options": ["20%", "125%", "80%", "18%"], "answer": 2, "explanation": "Efficiency = useful output/input = 8/10."}, {"id": 219, "category": "Applied Calculations and Practical Decisions", "question": "An ideal 20-tooth driving gear turns a 60-tooth driven gear. If the driver runs at 900 rpm, what is the driven speed magnitude?", "options": ["900 rpm", "2700 rpm", "30 rpm", "300 rpm"], "answer": 3, "explanation": "Driven speed = 900 × 20/60 = 300 rpm."}, {"id": 220, "category": "Applied Calculations and Practical Decisions", "question": "A repair needs 18 labor-hours. With three equally productive technicians working together, what ideal elapsed time is required?", "options": ["54 hours", "6 hours", "3 hours", "18 hours"], "answer": 1, "explanation": "18 labor-hours divided by 3 workers gives 6 hours, ignoring coordination losses."}, {"id": 221, "category": "Applied Calculations and Practical Decisions", "question": "A PM schedule contains 40 due tasks and 34 are completed on time. What is on-time compliance?", "options": ["117.6%", "34%", "15%", "85%"], "answer": 3, "explanation": "34/40 × 100 = 85%."}, {"id": 222, "category": "Applied Calculations and Practical Decisions", "question": "A part costs KWD 12 and 15 are required. What is the total before other charges?", "options": ["KWD 27", "KWD 0.80", "KWD 125", "KWD 180"], "answer": 3, "explanation": "12 × 15 = 180."}, {"id": 223, "category": "Applied Calculations and Practical Decisions", "question": "A 2 m steel bar has α = 12 × 10⁻⁶/K and warms by 50 K freely. What is its expansion?", "options": ["12 mm", "120 mm", "1.2 mm", "0.12 mm"], "answer": 2, "explanation": "ΔL = 12 × 10⁻⁶ × 2 × 50 m = 0.0012 m."}, {"id": 224, "category": "Applied Calculations and Practical Decisions", "question": "A pressure gauge reads 3 bar gauge while atmospheric pressure is 1 bar. What is absolute pressure?", "options": ["2 bar absolute", "4 bar absolute", "0.33 bar absolute", "3 bar absolute"], "answer": 1, "explanation": "Absolute pressure = gauge pressure + atmospheric pressure."}, {"id": 225, "category": "Applied Calculations and Practical Decisions", "question": "A critical pump is unavailable and its standby has an unresolved defect. What should the trainee supervisor do first?", "options": ["Escalate the service risk and coordinate a safe contingency with operations", "Hide the standby defect", "Assume the standby will work without checks", "Restart damaged equipment without assessment"], "answer": 0, "explanation": "A loss of redundancy requires an explicit risk assessment and coordinated response."}];
